CREATE TABLE `members` (
  `member_id` char(32) DEFAULT NULL,
  `ip_address` char(32) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `pswd` varchar(255) NOT NULL,
  `nom_postnom` varchar(100) DEFAULT NULL,
  `autre_nom` varchar(255) DEFAULT NULL,
  `genre` enum('Kamis','Kamite') DEFAULT NULL,
  `date_naissance` datetime DEFAULT NULL,
  `domaine_etude` varchar(255) DEFAULT NULL,
  `pays` char(100) DEFAULT NULL,
  `nationalite` varchar(100) DEFAULT NULL,
  `ville` char(36) DEFAULT NULL,
  `phone_number` varchar(20) DEFAULT NULL,
  `adresse` varchar(255) DEFAULT NULL,
  `niveau_initiation` enum('Pas encore initié','15 jours','30 jours','Neuvaine') DEFAULT NULL,
  `motivation` text NOT NULL,
  `ou_connu` text DEFAULT NULL,
  `path_profile` varchar(255) DEFAULT NULL,
  `bolokele` enum('0','1','2') NOT NULL DEFAULT '0',
  `token` varchar(150) DEFAULT NULL,
  `status` enum('attente_engagement','attente_integration','active','suspended','integration_rejetee','inactive','engagement_rejetee') DEFAULT 'inactive',
  `invited_by` varchar(36) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  UNIQUE KEY `member_id` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
